models.ConversationPost:
type ConversationPost = ChatPost & {
  reactions?: ChatReaction[];
  replies?: ChatPost[];
};

models.ChatPost:
type ChatPost = {
  id: string;
  author: string;
  initials: string;
  time: string;
  text: string;
  code?: string;
  resource?: { title: string; detail: string; href: string };
};

models.ChatReaction:
type ChatReaction = {
  emoji: string;
  label: string;
  count: number;
  mine: boolean;
};

models.ChatChannel:
type ChatChannel = {
  id: string;
  name: string;
  kind: "channel" | "direct";
  topic: string;
};
